DO $patch$
DECLARE def text;
BEGIN
 def:=pg_get_functiondef('public.reserve_sign_booking(uuid,text,jsonb,text)'::regprocedure);
 IF strpos(def,'payload:=jsonb_build_object')=0 OR strpos(def,' number:=public.generate_offer_number_for')=0 THEN RAISE EXCEPTION 'Reservation template changed'; END IF;
 def:=replace(def,'upload public.sign_permit_uploads;','upload public.sign_permit_uploads; extra record; ep public.b2b_managed_products; extra_qty int:=0; extra_gross int:=0; extra_items jsonb:=''[]''::jsonb;');
 def:=replace(def,' number:=public.generate_offer_number_for',E' IF jsonb_typeof(COALESCE(_body->''additionalSigns'',''[]''::jsonb)) <> ''array'' THEN RAISE EXCEPTION ''Ungültige Zusatzschilder''; END IF;\n FOR extra IN SELECT value AS item FROM jsonb_array_elements(COALESCE(_body->''additionalSigns'',''[]''::jsonb)) LOOP\n IF (extra.item->>''quantity'') IS NULL OR (extra.item->>''quantity'') !~ ''^[0-9]+$'' OR (extra.item->>''quantity'')::int NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION ''Ungültige Schilderanzahl''; END IF;\n SELECT * INTO ep FROM public.b2b_managed_products WHERE slug=extra.item->>''slug'' AND is_published AND category=''absperrtechnik'' AND (slug ILIKE ''%zusatz%'' OR slug LIKE ''vz-1000-%'') AND (COALESCE(cardinality(available_locations),0)=0 OR loc=ANY(available_locations));\n IF NOT FOUND THEN RAISE EXCEPTION ''Zusatzschild am Standort nicht verfügbar''; END IF;\n IF c->>''additionalSignGrossCents'' IS NULL OR (c->>''additionalSignGrossCents'')::int<=0 THEN RAISE EXCEPTION ''Zusatzschildpreis fehlt''; END IF;\n extra_qty:=extra_qty+(extra.item->>''quantity'')::int;\n IF extra_qty>100 THEN RAISE EXCEPTION ''Zu viele Zusatzschilder''; END IF;\n extra_gross:=extra_gross+(c->>''additionalSignGrossCents'')::int*(extra.item->>''quantity'')::int;\n extra_items:=extra_items||jsonb_build_array(jsonb_build_object(''id'',gen_random_uuid(),''product_slug'',ep.slug,''product_name'',ep.name,''description'',''Zusatzschild · pauschal für den Mietzeitraum'',''articles'',(extra.item->>''quantity'')::int,''quantity'',(extra.item->>''quantity'')::int,''duration'',1,''unit'',''pauschal'',''unit_price'',(c->>''additionalSignGrossCents'')::numeric/119.0,''discount_percent'',0,''start_date'',s,''end_date'',e));\n END LOOP;\n number:=public.generate_offer_number_for');
 def:=replace(def,' INSERT INTO public.rental_inquiries(',E' payload:=jsonb_set(payload,''{items}'',payload->''items''||extra_items);\n gross:=gross+extra_gross;\n payload:=jsonb_set(payload,''{totals}'',jsonb_build_object(''grossAmount'',gross/100.0,''netAmount'',round(gross/119.0,2),''vatAmount'',gross/100.0-round(gross/119.0,2)));\n INSERT INTO public.rental_inquiries(');
 EXECUTE def;
END; $patch$;